import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let args = command_string.split(" ").slice(1, command_string.split(" ").length)
        var i = 0
        while i < args.length {
            let arg = args[i]
            if arg.startsWith("--") {
                let kv = arg.slice(2).split("=")
                if kv.length == 2 {
                    let key = kv[0]
                    let value = kv[1]
                    arguments[key] = convert_type(key, value)
                } else {
                    let key = arg.slice(2)
                    arguments[key] = true
                }
            } else if arg.startsWith("-") {
                let key = arg.slice(1)
                if i + 1 < args.length && !args[i + 1].startsWith("-") {
                    arguments[key] = convert_type(key, args[i + 1])
                    i += 1
                } else {
                    arguments[key] = true
                }
            }
            i += 1
        }
        let missing_args = required.difference(HashSet<String>(arguments.keys()))
        if missing_args.isEmpty() {
            return (true, None)
        } else {
            return (false, Some(missing_args))
        }
    }

    public func get_argument(key: String): Any {
        return arguments.get(key).unwrap_or(None)
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if required {
            required.add(arg)
        }
        types[arg] = arg_type
    }

    public func convert_type(arg: String, value: String): Any {
        if types.contains(arg) {
            let type_info = types[arg]
            try {
                return value.parse(type_info)
            } catch (_) {
                return value
            }
        } else {
            return value
        }
    }
}

