        if (student.cources.size() == 0) {
            return None
        }
        var total: Float64 = 0.0
        for ((_, score) in student.cources) {
            total = total + score.toFloat64()
        }
        let gpa = total / student.cources.size().toFloat64()
        return Some(gpa)
    }

