        var count: Int64 = 0
        for ((_, student) in this.students) {
            if (student.cources.contains(course)) {
                let score = student.cources[course]
                total = total + score.toFloat64()
                count = count + 1
            }
        }
        if (count == 0) {
            return None
        }
        return Some(total / count.toFloat64())
    }

