import std.convert.Parsable

class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let max_length = max(num1.length(), num2.length())
        let padded_num1 = num1.zfill(max_length)
        let padded_num2 = num2.zfill(max_length)

        var carry = 0
        var result = []
        for (i in (max_length - 1)..=0) {
            let digit_sum = padded_num1[i].parseInt() + padded_num2[i].parseInt() + carry
            carry = digit_sum / 10
            let digit = digit_sum % 10
            result.insert(0, digit.toString())
        }

        if (carry > 0) {
            result.insert(0, carry.toString())
        }

        return result.join("")
    }

    public static func subtract(num1: String, num2: String): String {
        var negative = false
        let cmp_length = compareLengthOrLexicographically(num1, num2)
        if (cmp_length < 0) {
            let temp = num1
            num1 = num2
            num2 = temp
            negative = true
        } else if (cmp_length == 0) {
            if (num1.lexicalCompare(num2) < 0) {
                let temp = num1
                num1 = num2
                num2 = temp
                negative = true
            }
        }

        let max_length = max(num1.length(), num2.length())
        let padded_num1 = num1.zfill(max_length)
        let padded_num2 = num2.zfill(max_length)

        var borrow = 0
        var result = []
        for (i in (max_length - 1)..=0) {
            let digit_diff = padded_num1[i].parseInt() - padded_num2[i].parseInt() - borrow
            if (digit_diff < 0) {
                result.insert(0, (digit_diff + 10).toString())
                borrow = 1
            } else {
                result.insert(0, digit_diff.toString())
                borrow = 0
            }
        }

        while (result.length() > 1 && result[0] == "0") {
            result.removeAt(0)
        }

        if (negative && !(result.length() == 1 && result[0] == "0")) {
            result.insert(0, "-")
        }

        return result.join("")
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let len1 = num1.length()
        let len2 = num2.length()
        var result = [0] * (len1 + len2)

        for (i in (len1 - 1)..=0) {
            for (j in (len2 - 1)..=0) {
                let mul = num1[i].parseInt() * num2[j].parseInt()
                let p1 = i + j
                let p2 = i + j + 1
                let total = mul + result[p2]

                result[p1] += total / 10
                result[p2] = total % 10
            }
        }

        var start = 0
        while (start < result.length() - 1 && result[start] == 0) {
            start++
        }

        return result.slice(start, result.length()).map(item => item.toString()).join("")
    }
}

func compareLengthOrLexicographically(a: String, b: String): Int {
    if (a.length() < b.length()) return -1
    if (a.length() > b.length()) return 1
    return a.lexicalCompare(b)
}

