import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var num_buffer = ""

        for (char in expression) {
            if (char.isDigit() || char == '.') {
                num_buffer += char
            } else {
                if (num_buffer != "") {
                    match (Float64.parse(num_buffer)) {
                        Some(value) => {
                            operand_stack.add(value)
                        }
                        None => {
                            return None
                        }
                    }
                    num_buffer = ""
                }

                if (char in "+-*/^") {
                    while (!operator_stack.isEmpty() &&
                           operator_stack.getLast() != "(" &&
                           precedence(operator_stack.getLast()) >= precedence(char)) {
                        match (apply_operator(operand_stack, operator_stack)) {
                            (new_operands, new_ops) => {
                                operand_stack.clear()
                                operator_stack.clear()
                                for (op in new_operands) { operand_stack.add(op) }
                                for (op_str in new_ops) { operator_stack.add(op_str) }
                            }
                        }
                    }
                    operator_stack.add(char)
                } else if (char == '(') {
                    operator_stack.add(char)
                } else if (char == ')') {
                    while (!operator_stack.isEmpty() && operator_stack.getLast() != "(") {
                        match (apply_operator(operand_stack, operator_stack)) {
                            (new_operands, new_ops) => {
                                operand_stack.clear()
                                operator_stack.clear()
                                for (op in new_operands) { operand_stack.add(op) }
                                for (op_str in new_ops) { operator_stack.add(op_str) }
                            }
                        }
                    }
                    if (!operator_stack.isEmpty()) {
                        operator_stack.removeLast()
                    } else {
                        return None
                    }
                }
            }
        }

        if (num_buffer != "") {
            match (Float64.parse(num_buffer)) {
                Some(value) => {
                    operand_stack.add(value)
                }
                None => {
                    return None
                }
            }
        }

        while (!operator_stack.isEmpty()) {
            match (apply_operator(operand_stack, operator_stack)) {
                (new_operands, new_ops) => {
                    operand_stack.clear()
                    operator_stack.clear()
                    for (op in new_operands) { operand_stack.add(op) }
                    for (op_str in new_ops) { operator_stack.add(op_str) }
                }
            }
        }

        if (operand_stack.isEmpty()) {
            None
        } else {
            Some(operand_stack.getLast())
        }
    }

    public func precedence(op: String): Int64 {
        match (op) {
            "^" => 3
            "*" | "/" => 2
            "+" | "-" => 1
            _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        if (operand_stack.size() < 2 || operator_stack.isEmpty()) {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack.removeLast()
        let operand2 = operand_stack.removeLast()
        let operand1 = operand_stack.removeLast()

        let result = match (op) {
            "^" => operand1 ** operand2
            _ => {
                match (operators.get(op)) {
                    Some(func) => func(operand1, operand2)
                    None => return (operand_stack, operator_stack)
                }
            }
        }

        operand_stack.add(result)
        (operand_stack, operator_stack)
    }
}

