import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File::open(file_name, FileMode::Read)
        let reader = StreamReader(file)
        let lines = ArrayList<String>()
        var line: String? = nil
        while (line = reader.readLine()) != null {
            lines.add(line!!)
        }
        reader.close()
        file.close()

        if lines.isEmpty() {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()
        let titleParts = lines[0].split(",")
        for part in titleParts {
            title.add(part.trim())
        }

        for i in 1..lines.size() {
            let row = ArrayList<String>()
            let parts = lines[i].split(",")
            for part in parts {
                row.add(part.trim())
            }
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File::open(file_name, FileMode::Write)
            let writer = StreamWriter(file)
            for row in data {
                let line = String::join(row, ",")
                writer.writeLine(line)
            }
            writer.close()
            file.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if data.isEmpty() || N < 0 || N >= title.size() {
            return 0
        }

        let column_data = ArrayList<String>()
        for row in data {
            if N < row.size() {
                column_data.add(row[N].toUpperCase())
            }
        }

        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)
        new_data.add(column_data)

        let base_name = save_file_name.split(".")[0]
        let output_file = base_name + "_process.csv"
        return write_csv(new_data, output_file)
    }
}

