import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        if data.size() == 0 {
            return 0.0
        }
        var sum: Int64 = 0
        for value in data {
            sum += value
        }
        return round((sum as Float64) / (data.size() as Float64), 2)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        if data.size() == 0 {
            return 0.0
        }
        var sortedData = ArrayList<Int64>(data)
        sort(sortedData)
        var n = sortedData.size()
        if n % 2 == 0 {
            var mid = n / 2
            var left = sortedData[mid - 1]
            var right = sortedData[mid]
            return round(((left + right) as Float64) / 2.0, 2)
        } else {
            var mid = n / 2
            return sortedData[mid] as Float64
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if data.size() == 0 {
            return ArrayList<Int64>()
        }
        var counter = HashMap<Int64, Int64>()
        for value in data {
            if counter.contains(value) {
                counter[value] = counter[value] + 1
            } else {
                counter[value] = 1
            }
        }
        var maxCount = 0
        for count in counter.values() {
            if count > maxCount {
                maxCount = count
            }
        }
        var modes = ArrayList<Int64>()
        for entry in counter.entries() {
            if entry.getValue() == maxCount {
                modes.add(entry.getKey())
            }
        }
        sort(modes)
        return modes
    }
}

