import std.collection.ArrayList
import std.math.round
import std.math.sqrt
import std.math.abs

class DataStatistics2 {

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var sum: Float64 = 0.0
        for value in this.data {
            sum += value
        }
        return sum
    }

    public func get_min(): Float64 {
        var min: Float64 = this.data[0]
        for value in this.data {
            if value < min {
                min = value
            }
        }
        return min
    }

    public func get_max(): Float64 {
        var max: Float64 = this.data[0]
        for value in this.data {
            if value > max {
                max = value
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        let n: Int64 = this.data.size()
        if n == 0 {
            return 0.0
        }
        let mean: Float64 = this.get_sum() / n
        var sum_sq: Float64 = 0.0
        for value in this.data {
            sum_sq += (value - mean) * (value - mean)
        }
        let variance: Float64 = sum_sq / n
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        let variance: Float64 = this.get_variance()
        let std_dev: Float64 = sqrt(variance)
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        let n: Int64 = this.data.size()
        if n <= 1 {
            return 1.0
        }
        let mean: Float64 = this.get_sum() / n
        var sum_sq: Float64 = 0.0
        var sum_dev_sq: Float64 = 0.0
        for value in this.data {
            sum_sq += value * value
            sum_dev_sq += (value - mean) * (value - mean)
        }
        let variance: Float64 = sum_dev_sq / n
        if variance == 0.0 {
            return 1.0
        }
        let std_dev: Float64 = sqrt(variance)
        let expected_sum_sq: Float64 = n * mean * mean + sum_dev_sq
        if expected_sum_sq == 0.0 {
            return 1.0
        }
        return 1.0
    }
}

