import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n: Int64 = data1.size()
        let mean1: Float64 = data1.reduce(0.0, (acc, x) => acc + x) / n
        let mean2: Float64 = data2.reduce(0.0, (acc, x) => acc + x) / n

        let numerator: Float64 = data1.zip(data2).reduce(0.0, (acc, pair) => {
            let (x, y) = pair
            acc + (x - mean1) * (y - mean2)
        })

        let sum_sq1: Float64 = data1.reduce(0.0, (acc, x) => acc + (x - mean1) * (x - mean1))
        let sum_sq2: Float64 = data2.reduce(0.0, (acc, y) => acc + (y - mean2) * (y - mean2))
        let denominator: Float64 = sqrt(sum_sq1) * sqrt(sum_sq2)

        return denominator != 0.0 ? numerator / denominator : 0.0
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n: Int64 = data.size()
        let mean: Float64 = data.reduce(0.0, (acc, x) => acc + x) / n
        let variance: Float64 = data.reduce(0.0, (acc, x) => acc + (x - mean) * (x - mean)) / n
        let std_deviation: Float64 = sqrt(variance)

        if std_deviation == 0.0 {
            return 0.0
        }

        let skew: Float64 = data.reduce(0.0, (acc, x) => acc + (x - mean) * (x - mean) * (x - mean))
        return skew * n / ((n - 1) * (n - 2) * std_deviation * std_deviation * std_deviation)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n: Int64 = data.size()
        let mean: Float64 = data.reduce(0.0, (acc, x) => acc + x) / n
        let std_dev: Float64 = sqrt(data.reduce(0.0, (acc, x) => acc + (x - mean) * (x - mean)) / n)

        if std_dev == 0.0 {
            return Float64.nan()
        }

        let centered_data: ArrayList<Float64> = data.map(x => x - mean)
        let fourth_moment: Float64 = centered_data.reduce(0.0, (acc, x) => acc + x * x * x * x) / n
        let kurtosis_value: Float64 = (fourth_moment / (std_dev * std_dev * std_dev * std_dev)) - 3.0

        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coef: Float64 = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        return data.map(x => {
            let exponent: Float64 = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            coef * exp(exponent)
        })
    }
}

