import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(transform(expression))
        var result_stack = ArrayList<String>()
        postfix_stack.reverse()
        for item in postfix_stack {
            if !ExpressionCalculator.is_operator(item) {
                let cleaned = item.replace("~", "-")
                result_stack.append(cleaned)
            } else {
                let second_value = result_stack.pop().replace("~", "-")
                let first_value = result_stack.pop().replace("~", "-")
                let temp_result = ExpressionCalculator._calculate(Decimal(first_value), Decimal(second_value), item)
                result_stack.append(String(temp_result))
            }
        }
        let result_expr = result_stack.join("*")
        return Float64(eval(result_expr))
    }

    public func prepare(expression: String): Unit {
        var op_stack = ArrayList<String>([","])
        let arr = expression.chars().toList()
        var current_index = 0
        var count = 0
        for i in 0..arr.size() {
            let current_op = arr[i]
            if ExpressionCalculator.is_operator(current_op) {
                if count > 0 {
                    let token = arr.slice(current_index, current_index + count).join("")
                    postfix_stack.append(token)
                }
                var peek_op = op_stack.last()
                if current_op == ")" {
                    while op_stack.last() != "(" {
                        postfix_stack.append(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while current_op != "(" && peek_op != "," && compare(current_op, peek_op) {
                        postfix_stack.append(op_stack.pop())
                        peek_op = op_stack.last()
                    }
                    op_stack.append(current_op)
                }
                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }
        if count > 1 || (count == 1 && !ExpressionCalculator.is_operator(arr[current_index])) {
            let token = arr.slice(current_index, current_index + count).join("")
            postfix_stack.append(token)
        }
        while op_stack.last() != "," {
            postfix_stack.append(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        return c in {"+", "-", "*", "/", "(", ")", "%"}
    }

    public func compare(cur: String, peek: String): Bool {
        var current = cur
        var top_op = peek
        if current == "%" {
            current = "/"
        }
        if top_op == "%" {
            top_op = "/"
        }
        return operat_priority[Char(top_op).toInt() - 40] >= operat_priority[Char(current).toInt() - 40]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        if current_op == "+" {
            return first_value + second_value
        } else if current_op == "-" {
            return first_value - second_value
        } else if current_op == "*" {
            return first_value * second_value
        } else if current_op == "/" {
            return first_value / second_value
        } else if current_op == "%" {
            return first_value % second_value
        } else {
            panic("Unexpected operator: ${current_op}")
        }
    }

    public static func transform(expression: String): String {
        var cleaned = Regex("\\s+").replace_all(expression, "")
        cleaned = Regex("=$").replace_all(cleaned, "")
        var arr = cleaned.chars().toList()
        for i in 0..arr.size() {
            let c = arr[i]
            if c == "-" {
                if i == 0 {
                    arr[i] = "~"
                } else {
                    let prev_c = arr[i - 1]
                    if prev_c in {"+", "-", "*", "/", "(", "E", "e"} {
                        arr[i] = "~"
                    }
                }
            }
        }
        let result = arr.join("")
        if arr.size() > 0 && arr[0] == "~" && (arr.size() > 1 && arr[1] == "(") {
            return "0" + result
        } else {
            return result
        }
    }
}

