import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var dataMat: ArrayList<ArrayList<Int64>> = testData
        var P0: Float64 = 0.0
        for i in 0..<k {
            P0 += dataMat[i][i] * 1.0
        }
        var xsum: Float64 = 0.0
        var ysum: ArrayList<Float64> = ArrayList<Float64>()
        for i in 0..<k {
            var rowSum: Float64 = 0.0
            for j in 0..<k {
                rowSum += dataMat[i][j] * 1.0
            }
            xsum += rowSum
        }
        for j in 0..<k {
            var colSum: Float64 = 0.0
            for i in 0..<k {
                colSum += dataMat[i][j] * 1.0
            }
            ysum.append(colSum)
        }
        var sum: Float64 = xsum
        var Pe: Float64 = 0.0
        for j in 0..<k {
            Pe += (ysum[j] / sum) * (xsum / sum)
        }
        P0 = P0 / sum
        var cohens_coefficient: Float64 = (P0 - Pe) / (1 - Pe)
        return cohens_coefficient
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var dataMat: ArrayList<ArrayList<Int64>> = testData
        var P0: Float64 = 0.0
        var sum: Float64 = 0.0
        for i in 0..<N {
            var temp: Float64 = 0.0
            for j in 0..<k {
                sum += dataMat[i][j]
                temp += dataMat[i][j] * dataMat[i][j]
            }
            temp -= n
            temp /= (n - 1) * n
            P0 += temp
        }
        P0 = P0 / N
        var ysum: ArrayList<Float64> = ArrayList<Float64>()
        for j in 0..<k {
            var colSum: Float64 = 0.0
            for i in 0..<N {
                colSum += dataMat[i][j]
            }
            ysum.append(colSum)
        }
        var Pe: Float64 = 0.0
        for j in 0..<k {
            Pe += (ysum[j] / sum) * (ysum[j] / sum)
        }
        var ans: Float64 = (P0 - Pe) / (1 - Pe)
        return ans
    }
}

