import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.append(word)
    }

    public func find_longest_word(sentence: String): String {
        if (this.word_list.size() == 0) {
            return ""
        }
        let r = Regex(#"[\p{Punct}]"#)
        let no_punct = r.replaceAll(sentence, "")
        let words = no_punct.split(" ")
        let iter = words.iterator()
        var longest_word = ""
        while (true) {
            match (iter.next()) {
                case Some(word) =>
                    if (this.word_list.contains(word) && word.size() > longest_word.size()) {
                        longest_word = word
                    }
                case None => break
            }
        }
        return longest_word
    }
}

