import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        let pattern = Regex(#"[^a-zA-Z\s]"#)
        for (string in string_list) {
            let processed_string = pattern.replaceAll(string.toLowerCase(), "", -1)
            let words = processed_string.split(" ")
            var clean_words = ArrayList<String>()
            for (word in words) {
                let trimmed = word.trim()
                if (trimmed.length() > 0) {
                    clean_words.add(trimmed)
                }
            }
            words_list.add(clean_words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var word_frequency = HashMap<String, Int64>()
        for (words in words_list) {
            for (word in words) {
                if (word_frequency.containsKey(word)) {
                    word_frequency.set(word, word_frequency.get(word) + 1)
                } else {
                    word_frequency.set(word, 1)
                }
            }
        }
        var frequency_list = ArrayList<(String, Int64)>()
        for (entry in word_frequency.entries()) {
            frequency_list.add((entry.getKey(), entry.getValue()))
        }
        sort<(String, Int64), Int64>(
            frequency_list,
            key: { entry: (String, Int64) => return entry.1 },
            descending: true
        )
        var top_5 = HashMap<String, Int64>()
        let count = if (frequency_list.size() < 5) { frequency_list.size() } else { 5 }
        for (i in 0..count) {
            let entry = frequency_list.get(i)
            top_5.set(entry.0, entry.1)
        }
        return top_5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = self.process_data(string_list)
        return self.calculate_word_frequency(words_list)
    }
}

