import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for row in 0..<this.map.size() {
                let current_row = this.map.get(row)!
                for col in 0..<current_row.size() {
                    let cell = current_row.get(col)!
                    if cell == "O" {
                        this.player_row = row
                        this.player_col = col
                    } else if cell == "G" {
                        let target_pos = ArrayList<Int64>()
                        target_pos.add(row)
                        target_pos.add(col)
                        this.targets.add(target_pos)
                        this.target_count += 1
                    } else if cell == "X" {
                        let box_pos = ArrayList<Int64>()
                        box_pos.add(row)
                        box_pos.add(col)
                        this.boxes.add(box_pos)
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_on_target_count: Int64 = 0
        for box in this.boxes {
            for target in this.targets {
                if box.get(0) == target.get(0) && box.get(1) == target.get(1) {
                    box_on_target_count += 1
                    break
                }
            }
        }
        if box_on_target_count == this.target_count {
            this.is_game_over = true
        }
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_player_row = this.player_row
        var new_player_col = this.player_col

        if direction == "w" {
            new_player_row -= 1
        } else if direction == "s" {
            new_player_row += 1
        } else if direction == "a" {
            new_player_col -= 1
        } else if direction == "d" {
            new_player_col += 1
        }

        let map_row = this.map.get(new_player_row)
        if map_row != null && new_player_row >= 0 && new_player_col >= 0 && new_player_col < map_row.size() {
            let cell = map_row.get(new_player_col)
            if cell != null && cell != "#" {
                var box_at_new_pos: ?ArrayList<Int64> = null
                for box in this.boxes {
                    if box.get(0) == new_player_row && box.get(1) == new_player_col {
                        box_at_new_pos = box
                        break
                    }
                }

                if box_at_new_pos != null {
                    let box_row = box_at_new_pos.get(0)
                    let box_col = box_at_new_pos.get(1)
                    let push_row = box_row + (new_player_row - this.player_row)
                    let push_col = box_col + (new_player_col - this.player_col)

                    let push_map_row = this.map.get(push_row)
                    if push_map_row != null && push_row >= 0 && push_col >= 0 && push_col < push_map_row.size() {
                        let push_cell = push_map_row.get(push_col)
                        if push_cell != null && push_cell != "#" {
                            box_at_new_pos.set(0, push_row)
                            box_at_new_pos.set(1, push_col)
                            this.player_row = new_player_row
                            this.player_col = new_player_col
                        }
                    }
                } else {
                    this.player_row = new_player_row
                    this.player_col = new_player_col
                }
            }
        }
        return this.check_win()
    }
}

