    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        let new_item = Item(price, quantity)
        items.add(item, new_item)
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        let existing_item = items.get(item)
        if existing_item != None {
            let current = existing_item!
            current.quantity = current.quantity - quantity
            if current.quantity <= 0 {
                items.remove(item)
            } else {
                items.add(item, current)
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for pair in items.iterator() {
            let item = pair.value
            total = total + (item.price * item.quantity as Float64)
        }
        return total
    }
}

