import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data: ArrayList<Int64> = ArrayList<Int64>(data)
        sort(sorted_data)
        let n: Int64 = sorted_data.size()
        if (n % 2 == 1) {
            return sorted_data.get(n // 2).toFloat64()
        } else {
            return (sorted_data.get(n // 2 - 1).toFloat64() + sorted_data.get(n // 2).toFloat64()) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for value in data {
            counts.put(value, counts.get(value, 0) + 1)
        }
        let max_count: Int64 = counts.values().max()
        let mode_values: ArrayList<Int64> = ArrayList<Int64>()
        for entry in counts.entries() {
            if (entry.getValue() == max_count) {
                mode_values.add(entry.getKey())
            }
        }
        sort(mode_values)
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n: Int64 = x.size()
        if (n == 0 || n != y.size()) {
            return Option.none()
        }
        let mean_x: Float64 = mean(x).get()
        let mean_y: Float64 = mean(y).get()
        let mut numerator: Float64 = 0.0
        let mut sum_sq_x: Float64 = 0.0
        let mut sum_sq_y: Float64 = 0.0
        for i in 0..n {
            let xi: Float64 = x.get(i).toFloat64()
            let yi: Float64 = y.get(i).toFloat64()
            numerator += (xi - mean_x) * (yi - mean_y)
            sum_sq_x += (xi - mean_x) * (xi - mean_x)
            sum_sq_y += (yi - mean_y) * (yi - mean_y)
        }
        let denominator: Float64 = sqrt(sum_sq_x * sum_sq_y)
        if (denominator == 0.0) {
            return Option.none()
        }
        return Option.some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n: Int64 = data.size()
        if (n == 0) {
            return Option.none()
        }
        let mut sum: Int64 = 0
        for value in data {
            sum += value
        }
        return Option.some(sum.toFloat64() / n.toFloat64())
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let mut matrix: ArrayList<ArrayList<Float64>> = ArrayList<ArrayList<Float64>>()
        let num_cols: Int64 = data.get(0).size()
        for i in 0..num_cols {
            let row: ArrayList<Float64> = ArrayList<Float64>()
            for j in 0..num_cols {
                let column1: ArrayList<Int64> = ArrayList<Int64>()
                let column2: ArrayList<Int64> = ArrayList<Int64>()
                for k in 0..data.size() {
                    column1.add(data.get(k).get(i))
                    column2.add(data.get(k).get(j))
                }
                let corr: Option<Float64> = correlation(column1, column2)
                if (corr.isPresent()) {
                    row.add(corr.get())
                } else {
                    row.add(0.0)
                }
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n: Int64 = data.size()
        if (n < 2) {
            return Option.none()
        }
        let mean_value: Float64 = mean(data).get()
        let mut variance: Float64 = 0.0
        for x in data {
            let diff: Float64 = x.toFloat64() - mean_value
            variance += diff * diff
        }
        variance = variance / (n - 1).toFloat64()
        return Option.some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_val: Option<Float64> = mean(data)
        let std_dev: Option<Float64> = standard_deviation(data)
        if (!mean_val.isPresent() || !std_dev.isPresent() || std_dev.get() == 0.0) {
            return Option.none()
        }
        let mut result: ArrayList<Float64> = ArrayList<Float64>()
        let m: Float64 = mean_val.get()
        let s: Float64 = std_dev.get()
        for x in data {
            result.add((x.toFloat64() - m) / s)
        }
        return Option.some(result)
    }
}

