import std.collection.HashMap

class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.find("://")
        if scheme_end != -1 {
            return Option.Some(url[0..scheme_end])
        }
        return Option.None
    }

    public func get_host(): Option<String> {
        let scheme_end = url.find("://")
        if scheme_end != -1 {
            let start = scheme_end + 3
            let rest = url[start..]
            let host_end = rest.find("/")
            if host_end != -1 {
                return Option.Some(rest[0..host_end])
            } else {
                let fragment_index = rest.find("#")
                if fragment_index != -1 {
                    return Option.Some(rest[0..fragment_index])
                }
                return Option.Some(rest)
            }
        }
        return Option.None
    }

    public func get_path(): Option<String> {
        let scheme_end = url.find("://")
        var path_start = -1
        if scheme_end != -1 {
            path_start = scheme_end + 3
        } else {
            path_start = 0
        }
        let rest = url[path_start..]
        let host_end = rest.find("/")
        if host_end != -1 {
            return Option.Some(rest[host_end..])
        }
        let query_index = rest.find("?")
        if query_index != -1 {
            return Option.Some(rest[query_index..])
        }
        let fragment_index = rest.find("#")
        if fragment_index != -1 {
            return Option.Some(rest[fragment_index..])
        }
        return Option.None
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = url.find("?")
        if query_start != -1 {
            let fragment_start = url.find("#")
            let query_string = if fragment_start != -1 {
                url[query_start + 1..fragment_start]
            } else {
                url[query_start + 1..]
            }
            let params = HashMap<String, String>()
            if query_string.size > 0 {
                let pairs = query_string.split("&")
                for pair in pairs {
                    let kv = pair.split("=")
                    if kv.size == 2 {
                        params.put(kv[0], kv[1])
                    }
                }
            }
            return Option.Some(params)
        }
        return Option.None
    }

    public func get_fragment(): Option<String> {
        let fragment_start = url.find("#")
        if fragment_start != -1 {
            return Option.Some(url[fragment_start + 1..])
        }
        return Option.None
    }
}

