            if host_end != -1 {
                return Option.Some(rest[0..host_end])
            } else {
                let fragment_index = rest.find("#")
                if fragment_index != -1 {
                    return Option.Some(rest[0..fragment_index])
                }
                return Option.Some(rest)
            }
        }
        return Option.None
    }

    public func get_path(): Option<String> {
        let scheme_end = url.find("://")
        var path_start = -1
        if scheme_end != -1 {
            path_start = scheme_end + 3
        } else {
            path_start = 0
        }
        let rest = url[path_start..]
        let host_end = rest.find("/")
        if host_end != -1 {
            return Option.Some(rest[host_end..])
        }
        let query_index = rest.find("?")
        if query_index != -1 {
            return Option.Some(rest[query_index..])
        }
        let fragment_index = rest.find("#")
        if fragment_index != -1 {
            return Option.Some(rest[fragment_index..])
        }
        return Option.None
    }

