import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let len = vector_1.size()
        var dot_product: Float64 = 0.0
        var norm1: Float64 = 0.0
        var norm2: Float64 = 0.0

        for i in 0..<len {
            let v1 = vector_1[i]
            let v2 = vector_2[i]
            dot_product += v1 * v2
            norm1 += v1 * v1
            norm2 += v2 * v2
        }

        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }

        return dot_product / (sqrt(norm1) * sqrt(norm2))
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let len = vector_1.size()
        var norm1: Float64 = 0.0

        for i in 0..<len {
            let v = vector_1[i]
            norm1 += v * v
        }

        if norm1 == 0.0 {
            let result = ArrayList<Float64>()
            for _ in 0..<vectors_all.size() {
                result.append(0.0)
            }
            return result
        }

        norm1 = sqrt(norm1)
        let result = ArrayList<Float64>()

        for vector in vectors_all {
            var dot_product: Float64 = 0.0
            var norm2: Float64 = 0.0

            for i in 0..<len {
                let v1 = vector_1[i]
                let v2 = vector[i]
                dot_product += v1 * v2
                norm2 += v2 * v2
            }

            if norm2 == 0.0 {
                result.append(0.0)
            } else {
                let similarity = dot_product / (norm1 * sqrt(norm2))
                result.append(similarity)
            }
        }

        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.empty() || vector_list_2.empty() {
            return 0.0
        }

        let dim = vector_list_1[0].size()
        let mean_vector_1 = ArrayList<Float64>()
        let mean_vector_2 = ArrayList<Float64>()

        for _ in 0..<dim {
            mean_vector_1.append(0.0)
            mean_vector_2.append(0.0)
        }

        for vector in vector_list_1 {
            for i in 0..<dim {
                mean_vector_1[i] += vector[i]
            }
        }

        for vector in vector_list_2 {
            for i in 0..<dim {
                mean_vector_2[i] += vector[i]
            }
        }

        let size1 = vector_list_1.size()
        let size2 = vector_list_2.size()

        for i in 0..<dim {
            mean_vector_1[i] /= size1
            mean_vector_2[i] /= size2
        }

        return similarity(mean_vector_1, mean_vector_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()

        for (key, count) in number_dict {
            let value = log((total_num + 1) / (count + 1))
            result[key] = value
        }

        return result
    }
}

