        if this.orders.contains(order_id) {
            let order = this.orders.get(order_id).unwrap()
            order.status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        if this.orders.contains(order_id) {
            let order = this.orders.get(order_id).unwrap()
            return Option.some(order.status)
        } else {
            return Option.none()
        }
    }
}
